var verificationAttempts = new Map;
function getVerificationAttempt(email) {
  return verificationAttempts.get(email.trim().toLowerCase()) ?? null;
}
async function generateAndSaveVerificationCode(email) {
  const normalizedEmail = email.trim().toLowerCase();
  const code = Math.floor(1e4 + Math.random() * 90000).toString();
  const expiresAt = new Date(Date.now() + 15 * 60 * 1000);
  try {
    const db = getDb();
    await db.delete(verification).where(eq(verification.identifier, normalizedEmail));
    await db.insert(verification).values({
      id: `code_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
      identifier: normalizedEmail,
      value: code,
      expiresAt
    });
  } catch (err) {
    console.error("[EmailService] Failed to save 5-digit code to DB:", err);
  }
  return code;
}
async function verifyOtpCode({
  email,
  code
}) {
  const normalizedEmail = email.trim().toLowerCase();
  const cleanCode = code.trim();
  if (!cleanCode || cleanCode.length !== 5) {
    return {
      success: false,
      error: "Kode verifikasi harus terdiri dari 5 digit angka."
    };
  }
  try {
    const db = getDb();
    const now = new Date;
    const records = await db.select().from(verification).where(and(eq(verification.identifier, normalizedEmail), eq(verification.value, cleanCode), gte(verification.expiresAt, now)));
    if (!records.length) {
      return {
        success: false,
        error: "Kode verifikasi salah atau sudah kadaluarsa (berlaku 15 menit)."
      };
    }
    await db.update(user).set({
      emailVerified: true,
      updatedAt: new Date
    }).where(eq(user.email, normalizedEmail));
    await db.delete(verification).where(eq(verification.identifier, normalizedEmail));
    return { success: true };
  } catch (err) {
    console.error("[EmailService] Error verifying OTP code:", err);
    return {
      success: false,
      error: err instanceof Error ? err.message : "Terjadi kesalahan sistem saat verifikasi."
    };
  }
}
async function sendViaBrevo({
  to,
  name,
  subject,
  html
}) {
  const senderEmail = env.EMAIL_FROM.includes("<") ? env.EMAIL_FROM.split("<")[1]?.replace(">", "").trim() || "arulxxds@gmail.com" : env.EMAIL_FROM || "arulxxds@gmail.com";
  const senderName = env.EMAIL_FROM.includes("<") ? env.EMAIL_FROM.split("<")[0]?.replace(/"/g, "").trim() || "LifeSync Wellness" : "LifeSync Wellness";
  const res = await fetch("https://api.brevo.com/v3/smtp/email", {
    method: "POST",
    headers: {
      accept: "application/json",
      "content-type": "application/json",
      "api-key": env.BREVO_API_KEY
    },
    body: JSON.stringify({
      sender: {
        name: senderName,
        email: senderEmail
      },
      to: [{ email: to, name: name || to }],
      subject,
      htmlContent: html
    })
  });
  if (!res.ok) {
    const errorText = await res.text();
    return { ok: false, error: `Brevo error (${res.status}): ${errorText}` };
  }
  const data = await res.json();
  return { ok: true, messageId: data.messageId };
}
