// src/utils/response.ts
function sendSuccess(res, data, statusCode = 200) {
  const payload = {
    success: true,
    data
  };
  res.status(statusCode).json(payload);
}
function sendError(res, statusCode, code, message, details) {
  const payload = {
    success: false,
    error: {
      code,
      message,
      ...details !== undefined ? { details } : {}
    }
  };
  res.status(statusCode).json(payload);
}

