// src/middleware/auth.ts
async function requireAuth(req, res, next) {
  try {
    const sessionData = await auth2.api.getSession({
      headers: fromNodeHeaders(req.headers)
    });
    if (!sessionData || !sessionData.user) {
      sendError(res, 401, "UNAUTHORIZED", "Authentication required. Please sign in.");
      return;
    }
    const rawUser = sessionData.user;
    if (rawUser.banned) {
      sendError(res, 403, "ACCOUNT_SUSPENDED", "Your account has been suspended.");
      return;
    }
    if (env.REQUIRE_EMAIL_VERIFICATION && !rawUser.emailVerified) {
      sendError(res, 403, "EMAIL_NOT_VERIFIED", "Email verification required. Please verify your Gmail address to access LifeSync.");
      return;
    }
    req.user = {
      id: rawUser.id,
      name: rawUser.name,
      email: rawUser.email,
      emailVerified: rawUser.emailVerified,
      image: rawUser.image,
      role: rawUser.role === "ADMIN" ? "ADMIN" : "USER",
      banned: Boolean(rawUser.banned)
    };
    req.authSession = {
      id: sessionData.session.id,
      userId: sessionData.session.userId,
      expiresAt: new Date(sessionData.session.expiresAt)
    };
    next();
  } catch (error) {
    console.error("[Auth Middleware Error]:", error);
    sendError(res, 401, "UNAUTHORIZED", "Invalid or expired session");
  }
}
function requireRole(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      sendError(res, 401, "UNAUTHORIZED", "Authentication required");
      return;
    }
    if (!allowedRoles.includes(req.user.role)) {
      sendError(res, 403, "FORBIDDEN", "You do not have permission to access this resource");
      return;
    }
    next();
  };
}

// src/middleware/validate.ts
function validateBody(schema) {
  return (req, res, next) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      sendError(res, 400, "VALIDATION_ERROR", "Request validation failed", result.error.flatten());
      return;
    }
    req.body = result.data;
    next();
  };
}
function errorHandler(err, _req, res, _next) {
  if (err instanceof ZodError) {
    sendError(res, 400, "VALIDATION_ERROR", "Invalid request data", err.flatten());
    return;
  }
  const message = err instanceof Error ? err.message : "Internal server error";
  console.error("[API Error]:", err);
  sendError(res, 500, "INTERNAL_SERVER_ERROR", message);
}

