// src/services/admin.service.ts
async function getPlatformStats() {
  const db = getDb();
  const [
    usersCountRows,
    activeUsersRows,
    categoriesRows,
    schedulesCountRows,
    tipsCountRows
  ] = await Promise.all([
    db.select({ count: sql3`count(*)::int` }).from(user),
    db.select({
      count: sql3`count(distinct ${session.userId})::int`
    }).from(session),
    db.select({ count: sql3`count(*)::int` }).from(activities),
    db.select({ count: sql3`count(*)::int` }).from(dailySchedules),
    db.select({ count: sql3`count(*)::int` }).from(healthTips)
  ]);
  const allUsers = await db.select({
    role: user.role,
    banned: user.banned
  }).from(user);
  const adminCount = allUsers.filter((u) => u.role === "ADMIN").length;
  const bannedCount = allUsers.filter((u) => u.banned).length;
  return {
    totalRegisteredUsers: usersCountRows[0]?.count ?? 0,
    activeSessionUsers: activeUsersRows[0]?.count ?? 0,
    adminUsersCount: adminCount,
    suspendedUsersCount: bannedCount,
    totalCategoriesCount: categoriesRows[0]?.count ?? 0,
    totalScheduledBlocksCount: schedulesCountRows[0]?.count ?? 0,
    totalWellnessTipsCount: tipsCountRows[0]?.count ?? 0
  };
}
async function listAllUsersForAdmin() {
  const db = getDb();
  const usersList = await db.select({
    id: user.id,
    name: user.name,
    email: user.email,
    emailVerified: user.emailVerified,
    role: user.role,
    banned: user.banned,
    createdAt: user.createdAt,
    updatedAt: user.updatedAt
  }).from(user).orderBy(desc(user.createdAt));
  return usersList;
}
async function updateUserByAdmin(targetUserId, adminUserId, input) {
  const db = getDb();
  const existing = await db.select().from(user).where(eq(user.id, targetUserId)).limit(1);
  if (!existing[0]) {
    return { error: "NOT_FOUND", message: "Target user not found." };
  }
  if (targetUserId === adminUserId) {
    if (input.role && input.role !== "ADMIN") {
      return {
        error: "SELF_DEMOTION_FORBIDDEN",
        message: "Administrators cannot remove their own ADMIN role."
      };
    }
    if (input.banned === true) {
      return {
        error: "SELF_BAN_FORBIDDEN",
        message: "Administrators cannot suspend their own account."
      };
    }
  }
  const updates = {
    updatedAt: new Date
  };
  if (input.role !== undefined)
    updates.role = input.role;
  if (input.banned !== undefined)
    updates.banned = input.banned;
  await db.update(user).set(updates).where(eq(user.id, targetUserId));
  const updated = await db.select({
    id: user.id,
    name: user.name,
    email: user.email,
    emailVerified: user.emailVerified,
    role: user.role,
    banned: user.banned,
    createdAt: user.createdAt,
    updatedAt: user.updatedAt
  }).from(user).where(eq(user.id, targetUserId)).limit(1);
  return { data: updated[0] };
}
async function listSystemAndAllCategoriesForAdmin() {
  const db = getDb();
  return db.select().from(activities).orderBy(desc(activities.isSystem), asc(activities.name));
}
async function createSystemCategoryByAdmin(adminId, input) {
  return createCustomCategory(adminId, input, true);
}
async function updateCategoryByAdmin(categoryId, adminId, input) {
  return updateCategory(categoryId, adminId, "ADMIN", input);
}
async function deleteCategoryByAdmin(categoryId, adminId) {
  return deleteCategory(categoryId, adminId, "ADMIN");
}
async function listAllTipsForAdmin() {
  const db = getDb();
  return db.select().from(healthTips).orderBy(desc(healthTips.createdAt));
}
async function createWellnessTipByAdmin(adminId, input) {
  const db = getDb();
  const newTip = {
    id: `tip_${crypto.randomUUID()}`,
    title: input.title.trim(),
    category: input.category.trim(),
    content: input.content.trim(),
    actionLabel: input.actionLabel?.trim() || null,
    icon: input.icon || "lightbulb",
    isActive: input.isActive ?? true,
    createdBy: adminId,
    createdAt: new Date,
    updatedAt: new Date
  };
  await db.insert(healthTips).values(newTip);
  return newTip;
}
async function updateWellnessTipByAdmin(tipId, input) {
  const db = getDb();
  const existing = await db.select().from(healthTips).where(eq(healthTips.id, tipId)).limit(1);
  if (!existing[0]) {
    return { error: "NOT_FOUND" };
  }
  const updates = {
    updatedAt: new Date
  };
  if (input.title !== undefined)
    updates.title = input.title.trim();
  if (input.category !== undefined)
    updates.category = input.category.trim();
  if (input.content !== undefined)
    updates.content = input.content.trim();
  if (input.actionLabel !== undefined)
    updates.actionLabel = input.actionLabel?.trim() || null;
  if (input.icon !== undefined)
    updates.icon = input.icon;
  if (input.isActive !== undefined)
    updates.isActive = input.isActive;
  await db.update(healthTips).set(updates).where(eq(healthTips.id, tipId));
  const refreshed = await db.select().from(healthTips).where(eq(healthTips.id, tipId)).limit(1);
  return { data: refreshed[0] };
}
async function deleteWellnessTipByAdmin(tipId) {
  const db = getDb();
  const existing = await db.select().from(healthTips).where(eq(healthTips.id, tipId)).limit(1);
  if (!existing[0]) {
    return { error: "NOT_FOUND" };
  }
  await db.delete(healthTips).where(eq(healthTips.id, tipId));
  return { data: { id: tipId, deleted: true } };
}

