// src/app.ts
function createApp() {
  const app = import_express9.default();
  const authHandler = toNodeHandler2(auth2);
  app.use(import_cors.default({
    origin: [env.FRONTEND_URL, "http://localhost:3000", "http://127.0.0.1:3000"],
    credentials: true,
    methods: ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"],
    allowedHeaders: ["Content-Type", "Authorization", "Cookie"]
  }));
  app.all("/api/auth/*", (req, res) => {
    authHandler(req, res);
  });
  app.use(import_express9.default.json({ limit: "1mb" }));
  app.use(import_express9.default.urlencoded({ extended: true }));
  const rootHandler = (_req, res) => {
    res.json({
      service: "LifeSync Wellness API",
      status: "online",
      version: "0.1.0",
      documentation: "/api/health-check"
    });
  };
  app.get("/", rootHandler);
  app.get("/api", rootHandler);
  app.use("/api", apiRouter);
  app.use((_req, res) => {
    sendError(res, 404, "NOT_FOUND", "The requested endpoint does not exist");
  });
  app.use(errorHandler);
  return app;
}

// src/serverless.ts
var app;
function handler(req, res) {
  try {
    if (!app) {
      app = createApp();
    }
    return app(req, res);
  } catch (error) {
    console.error("[Vercel Serverless Error]:", error);
    res.statusCode = 500;
    res.setHeader("Content-Type", "application/json");
    res.end(JSON.stringify({
      error: "SERVER_INITIALIZATION_FAILED",
      message: error?.message || String(error),
      envCheck: {
        hasDatabaseUrl: Boolean(process.env.DATABASE_URL),
        hasBetterAuthSecret: Boolean(process.env.BETTER_AUTH_SECRET),
        betterAuthUrl: process.env.BETTER_AUTH_URL || "(not set)"
      }
    }));
  }
}
